                                                                                                                                                                                                                                                                                                                                                                                                                                               
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TENANT_EVENT_LIBRARY_V" ("FIRST_EVENT_CATEGORY_ID", "FIRST_EVENT_CATEGORY_NAME", "FIRST_EVENT_CATEGORY_CODE", "SECOND_EVENT_CATEGORY_ID", "SECOND_EVENT_CATEGORY_NAME", "SECOND_EVENT_CATEGORY_CODE", "EVENT_PHENOMENON_ID", "EVENT_PHENOMENON_NAME", "EVENT_PHENOMENON_CODE", "FULL_CODE", "SORT_NUM", "TENANT_ID", "EVENT_LIBRARY_ID", "IS_HIDE", "IS_ENABLE", "BASE_DEPT_ID") AS     
  select p.EVENT_CATEGORY_ID                         as FIRST_EVENT_CATEGORY_ID                                                                                                                                                                                                                                                                                                                                                                
     , p.NAME                                      as first_EVENT_CATEGORY_NAME                                                                                                                                                                                                                                                                                                                                                                
     , p.CODE                                      as first_EVENT_CATEGORY_CODE                                                                                                                                                                                                                                                                                                                                                                
     , sub.EVENT_CATEGORY_ID                       as SECOND_EVENT_CATEGORY_ID                                                                                                                                                                                                                                                                                                                                                                 
     , sub.NAME                                    as second_EVENT_CATEGORY_NAME                                                                                                                                                                                                                                                                                                                                                               
     , sub.CODE                                    as second_EVENT_CATEGORY_CODE                                                                                                                                                                                                                                                                                                                                                               
     , ph.PHENOMENON_ID                            as EVENT_PHENOMENON_ID                                                                                                                                                                                                                                                                                                                                                                      
     , ph.NAME                                     as EVENT_PHENOMENON_NAME                                                                                                                                                                                                                                                                                                                                                                    
     , ph.CODE                                     as EVENT_PHENOMENON_CODE                                                                                                                                                                                                                                                                                                                                                                    
     , p.CODE || '#' || sub.CODE || '#' || ph.CODE as full_CODE                                                                                                                                                                                                                                                                                                                                                                                
     , lib.SORT_NUM                                                                                                                                                                                                                                                                                                                                                                                                                            
     , lib.TENANT_ID                                                                                                                                                                                                                                                                                                                                                                                                                           
     , lib.EVENT_LIBRARY_ID                                                                                                                                                                                                                                                                                                                                                                                                                    
     , lib.IS_HIDE                                                                                                                                                                                                                                                                                                                                                                                                                             
     , lib.IS_ENABLE                                                                                                                                                                                                                                                                                                                                                                                                                           
     , lib.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                               
from TENANT_EVENT_LIBRARY lib                                                                                                                                                                                                                                                                                                                                                                                                                  
         inner join TENANT_EVENT_CATEGORY sub                                                                                                                                                                                                                                                                                                                                                                                                  
                    on sub.CODE = lib.CATEGORY_SECOND_CODE and sub.DEL_FLAG = 0 and SUB.TENANT_ID = lib.TENANT_ID and                                                                                                                                                                                                                                                                                                                          
                       sub.BASE_DEPT_ID = lib.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                     
         inner join TENANT_EVENT_CATEGORY p                                                                                                                                                                                                                                                                                                                                                                                                    
                    on p.CODE = sub.PARENT_CODE and p.DEL_FLAG = 0 and p.TENANT_ID = lib.TENANT_ID and                                                                                                                                                                                                                                                                                                                                         
                       p.BASE_DEPT_ID = lib.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                       
         inner join TENANT_EVENT_PHENOMENON ph                                                                                                                                                                                                                                                                                                                                                                                                 
                    on ph.CODE = lib.PHENOMENON_CODE and ph.DEL_FLAG = 0 and ph.TENANT_ID = lib.TENANT_ID and                                                                                                                                                                                                                                                                                                                                  
                       ph.BASE_DEPT_ID = lib.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                      
where lib.IS_HIDE = 0;                                                                                                                                                                                                                                                                                                                                                                                                                         

